    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            AtomicTally single = new AtomicTally();
            single.record();
            single.record();
            single.record();
            check("three record() calls on one thread (safe)", 3, single.safeCount());
            check("three record() calls on one thread (unsafe)", 3, single.unsafeCount());

            AtomicTally none = AtomicTally.hammer(0, 5000);
            check("hammer with no threads records nothing", 0, none.safeCount());

            AtomicTally one = AtomicTally.hammer(1, 1000);
            check("one thread, 1000 increments", 1000, one.safeCount());
            check("one thread cannot lose updates", 1000, one.unsafeCount());

            AtomicTally busy = AtomicTally.hammer(4, 20000);
            check("4 threads x 20000 is exact with AtomicInteger", 80000, busy.safeCount());
            check("the plain int never OVERcounts", Boolean.TRUE,
                    Boolean.valueOf(busy.unsafeCount() <= 80000));
            check("hammer really joined its threads (count is final)", 80000, busy.safeCount());
        } catch (InterruptedException e) {
            System.out.println("FAIL  the test thread was interrupted -- " + e);
            failures++;
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
        System.exit(0);
    }
}

