import java.util.concurrent.atomic.AtomicInteger;

/**
 * TASK: Show the difference between an AtomicInteger and a plain int field.
 *
 * Every call to record() must bump BOTH counters:
 *   - safeHits  : an AtomicInteger, incremented atomically (incrementAndGet)
 *   - unsafeHits: an ordinary int, incremented with the classic unsafeHits++
 *
 * hammer(threads, perThread) must:
 *   1. create one AtomicTally,
 *   2. start exactly "threads" threads, each calling record() "perThread" times,
 *   3. JOIN every thread,
 *   4. return that AtomicTally.
 *
 * After hammer(4, 20000) the safe count is EXACTLY 80000 every single time,
 * while the unsafe count is 80000 or less -- lost updates from the read /
 * add / write race in unsafeHits++. hammer(0, n) starts no threads and
 * returns a tally with both counts at 0.
 */
public class AtomicTally {

    private final AtomicInteger safeHits = new AtomicInteger(0);
    private int unsafeHits = 0;

    public void record() {
        safeHits.incrementAndGet();
        unsafeHits++;
    }

    public int safeCount() {
        return safeHits.get();
    }

    public int unsafeCount() {
        return unsafeHits;
    }

    public static AtomicTally hammer(int threads, int perThread) throws InterruptedException {
        AtomicTally tally = new AtomicTally();
        Thread[] workers = new Thread[Math.max(threads, 0)];
        for (int i = 0; i < workers.length; i++) {
            workers[i] = new Thread(() -> {
                for (int j = 0; j < perThread; j++) {
                    tally.record();
                }
            });
            workers[i].start();
        }
        for (Thread worker : workers) {
            worker.join();
        }
        return tally;
    }
}
